/**
 * SchemeBridge — Audio STT Verification via Sarvam saaras:v4
 * 
 * Verifies that the audio generated by Sarvam Bulbul v3 for the 7 regional languages
 * (te, bn, gu, kn, ml, pa, or) round-trips back to the expected target language script
 * and words when transcribed by Sarvam Saaras v4 STT.
 * 
 * STRICT SECURITY:
 * Never prints or leaks SARVAM_API_KEY.
 */

const fs = require('fs');
const path = require('path');

// Load environment variables from backend/.env
const envPath = path.resolve(__dirname, '../backend/.env');
if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  envContent.split('\n').forEach(line => {
    const match = line.match(/^\s*([\w.-]+)\s*=\s*(.*)?\s*$/);
    if (match && !process.env[match[1]]) {
      process.env[match[1]] = (match[2] || '').trim();
    }
  });
}

const SARVAM_API_KEY = (process.env.SARVAM_API_KEY || '').trim();
if (!SARVAM_API_KEY) {
  console.error('ERROR: SARVAM_API_KEY is not configured in backend/.env');
  process.exit(1);
}

const UNICODE_RANGES = {
  te: [0x0c00, 0x0c7f],
  bn: [0x0980, 0x09ff],
  gu: [0x0a80, 0x0aff],
  kn: [0x0c80, 0x0cff],
  ml: [0x0d00, 0x0d7f],
  pa: [0x0a00, 0x0a7f],
  or: [0x0b00, 0x0b7f]
};

function calculateScriptPurity(text, lang) {
  const range = UNICODE_RANGES[lang];
  if (!range) return 100;
  let targetCount = 0;
  let letterCount = 0;
  for (const char of text) {
    if (/[\s\d\p{P}\p{S}]/u.test(char)) continue;
    letterCount++;
    const cp = char.codePointAt(0);
    if (cp >= range[0] && cp <= range[1]) {
      targetCount++;
    }
  }
  return letterCount > 0 ? (targetCount / letterCount) * 100 : 100;
}

function normalizeWords(text) {
  if (!text) return [];
  return text
    .toLowerCase()
    .replace(/[।.,!?;:"'—–\-()\[\]{}]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ')
    .filter(Boolean);
}

function calculateWordMatch(sourceText, transcriptText) {
  const sourceWords = normalizeWords(sourceText);
  const transcriptWords = new Set(normalizeWords(transcriptText));
  if (sourceWords.length === 0) return 100;
  let matched = 0;
  for (const w of sourceWords) {
    if (transcriptWords.has(w)) matched++;
  }
  return (matched / sourceWords.length) * 100;
}

async function transcribeClip(filePath) {
  const fileBuf = fs.readFileSync(filePath);
  const blob = new Blob([fileBuf], { type: 'audio/mpeg' });

  const formData = new FormData();
  formData.append('file', blob, path.basename(filePath));
  formData.append('model', 'saaras:v4');
  formData.append('mode', 'transcribe');

  const res = await fetch('https://api.sarvam.ai/speech-to-text', {
    method: 'POST',
    headers: {
      'api-subscription-key': SARVAM_API_KEY
    },
    body: formData
  });

  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`STT failed (HTTP ${res.status}): ${errText}`);
  }

  const json = await res.json();
  return json.transcript || '';
}

async function main() {
  const manifestPath = path.resolve(__dirname, '../frontend/public/audio/audio-manifest.json');
  if (!fs.existsSync(manifestPath)) {
    console.error('Audio manifest not found at:', manifestPath);
    process.exit(1);
  }

  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  const testLangs = ['te', 'bn', 'gu', 'kn', 'ml', 'pa', 'or'];
  const testClipId = 'portal_welcome';

  console.log('=============================================================================');
  console.log('   Sarvam Saaras v4 STT Round-Trip Audio Verification (Sample Testing)       ');
  console.log('=============================================================================\n');
  console.log('| Language | Clip ID          | Transcribed Text (sample)               | Script % | Word Match % | Status |');
  console.log('|:---------|:-----------------|:----------------------------------------|:--------:|:------------:|:------:|');

  let allPassed = true;
  const results = [];

  for (const lang of testLangs) {
    const clipInfo = manifest.clips[testClipId] && manifest.clips[testClipId][lang];
    if (!clipInfo) {
      console.error(`Clip not found for lang: ${lang}`);
      allPassed = false;
      continue;
    }

    const fullPath = path.resolve(__dirname, '../frontend/public' + clipInfo.path);
    try {
      const transcript = await transcribeClip(fullPath);
      const scriptPct = calculateScriptPurity(transcript, lang);
      const wordMatchPct = calculateWordMatch(clipInfo.text, transcript);
      const passed = scriptPct >= 90.0 && wordMatchPct >= 60.0;

      if (!passed) allPassed = false;

      const shortTrans = (transcript || '').replace(/\s+/g, ' ').slice(0, 38);
      console.log(`| ${lang.padEnd(8)} | ${testClipId.padEnd(16)} | ${shortTrans.padEnd(38)} | ${scriptPct.toFixed(1).padStart(7)}% | ${wordMatchPct.toFixed(1).padStart(11)}% | ${passed ? 'PASS' : 'FAIL'} |`);

      results.push({
        lang,
        clipId: testClipId,
        sourceText: clipInfo.text,
        transcript,
        scriptPct,
        wordMatchPct,
        passed
      });
    } catch (err) {
      console.error(`| ${lang.padEnd(8)} | ${testClipId.padEnd(16)} | ERROR: ${err.message.slice(0, 30)} |   0.0% |         0.0% | FAIL |`);
      allPassed = false;
    }
  }

  console.log('\n-----------------------------------------------------------------------------');
  if (allPassed) {
    console.log('STT AUDIT SUCCESS: All 7 languages transcribed into their native scripts with >= 90% purity and >= 60% word overlap.');
    console.log('Note: Automation passes technical checks; pronunciation NOT VERIFIED until a native speaker signs off.');
  } else {
    console.error('STT AUDIT WARNING: One or more clips failed the round-trip threshold.');
  }
  console.log('=============================================================================\n');

  if (!allPassed) {
    process.exit(1);
  }
}

main().catch(err => {
  console.error('Execution error:', err);
  process.exit(1);
});
